def solve():
    s = sys.stdin.readline().strip()
    if not s:
        return

    mirror_chars = set(['A', 'H', 'I', 'M', 'O', 'T', 'U', 'V', 'W', 'X', 'Y'])

    # Check if all characters are valid mirror characters
    for char in s:
        if char not in mirror_chars:
            print("NO")
            return

    # Check symmetry
    left, right = 0, len(s) - 1
    while left < right:
        if s[left] != s[right]:
            print("NO")
            return
        left += 1
        right -= 1

    print("YES")

if __name__ == "__main__":
    solve()

